use maho_rpc::session_worker_protocol::*;
#[test]fn host_envelopes_preserve_tags_and_optional_connection(){for value in [serde_json::json!({"type":"prepare","request":1,"configuration":{},"profile":{}}),serde_json::json!({"type":"commit","request":2}),serde_json::json!({"type":"bind","request":3,"sessionId":"lease","display":{"revision":1.0,"width":80.0,"rendered":false,"capabilities":[]}}),serde_json::json!({"type":"command","request":4,"command":{"type":"abort"},"connection":"peer","display":{"revision":1.0,"width":80.0,"rendered":false,"capabilities":[]}}),serde_json::json!({"type":"display","display":{"revision":1.0,"width":80.0,"rendered":false,"capabilities":[]}}),serde_json::json!({"type":"cancel_ui"}),serde_json::json!({"type":"close"})]{let parsed:HostToSessionWorker=serde_json::from_value(value.clone()).unwrap();assert_eq!(serde_json::to_value(parsed).unwrap(),value);}}
